// Fails the build when an image under public/assets is oversized or when a
// data file references an officer photo whose generated variants are missing.
//
// Every image under public/assets is checked against a per-directory budget;
// the most specific matching directory wins:
//   public/assets/officerpics  200 KB, 1200 px  (generated by officer-photos.mjs)
//   public/assets/**           400 KB, 2048 px  (everything else)
import sharp from "sharp";
import { readdir, readFile, stat } from "node:fs/promises";
import path from "node:path";

const RULES = [
  { dir: "public/assets", maxKB: 400, maxPx: 2048 },
  { dir: "public/assets/officerpics", maxKB: 200, maxPx: 1200 },
];
const DATA_FILES = ["src/data/officers.ts", "src/data/alumni.ts"];
const WIDTHS = [300, 600];

const errors = [];

async function* walk(dir) {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(p);
    else yield p;
  }
}

for await (const p of walk("public/assets")) {
  if (!/\.(webp|jpe?g|png|avif|gif)$/i.test(p)) continue;
  const rule = RULES.filter((r) => p.startsWith(`${r.dir}/`)).sort(
    (a, b) => b.dir.length - a.dir.length,
  )[0];
  const { size } = await stat(p);
  const { width = 0, height = 0 } = await sharp(p).metadata();
  if (size > rule.maxKB * 1024) errors.push(`${p}: ${(size / 1024).toFixed(0)} KB exceeds ${rule.maxKB} KB`);
  if (width > rule.maxPx || height > rule.maxPx) errors.push(`${p}: ${width}x${height} exceeds ${rule.maxPx}px`);
}

for (const file of DATA_FILES) {
  const text = await readFile(file, "utf8");
  for (const [, base] of text.matchAll(/photo:\s*"\/assets\/officerpics\/([^"]+)"/g)) {
    for (const w of WIDTHS) {
      const variant = `public/assets/officerpics/${base}-${w}.webp`;
      await stat(variant).catch(() => errors.push(`${file}: missing ${variant} (run npm run img:officers)`));
    }
  }
}

if (errors.length) {
  console.error(errors.join("\n"));
  process.exit(1);
}
console.log("Assets OK");
